const levels = [
  ['閃亮出道舞台','屋頂上的小派對','🎤',['🎀','⭐','🎵','🦋','🍓','💎','🌸','🎁','🍭','💜']],
  ['甜甜點心時光','今天吃一口幸福','🧁',['🍰','🍒','🍩','🍬','🍓','🧁','🍪','🍭','🍎','🍊']],
  ['女團練習日','跟著音樂動一動','🎧',['🎵','🎤','🎧','⭐','🎀','💜','💿','🎸','🌸','💎']],
  ['海底星光旅行','和魚兒打個招呼','🐠',['🐠','🐚','🫧','🪸','⭐','🐙','🦀','🐟','💎','🐬']],
  ['花園野餐趣','把好心情裝進籃子','🌷',['🌷','🌼','🍎','🦋','🍓','🌻','🍒','🍄','🌸','🍊']],
  ['糖果遊樂園','今天的快樂加倍','🎠',['🎈','🍭','🎁','🍬','🎀','⭐','🍩','🎪','🧸','💜']],
  ['月光睡衣派對','和星星說晚安','🌙',['🌙','⭐','🧸','☁️','💜','📚','🎀','🕯️','💎','🌟']],
  ['海邊的假期','收集一口袋陽光','🏖️',['🐚','🦀','🐠','🌞','🍉','🩴','🍦','⛵','🌴','🐬']],
  ['魔法圖書館','故事裡的小秘密','📚',['📚','🗝️','💎','🪄','⭐','🔮','🕯️','🦋','🌙','🎀']],
  ['彩虹安可演唱會','把閃亮帶給全世界','🌈',['🌈','🎤','🎵','🎉','🎀','⭐','💜','🎁','💎','🌸']]
];
const regions = [[[18.5, 4, 3, 4], [55, 28, 5, 6], [93, 51, 7, 10], [95, 67, 7, 9], [2, 66, 5, 14], [4, 37, 3, 10], [26, 70, 7, 9], [36, 81, 3, 4], [50, 80, 6, 6], [67, 85, 4, 4]], [[45, 4, 7, 5], [47, 15, 4, 5], [75, 25, 4, 4], [12, 85, 5, 12], [35, 91, 7, 7], [56, 93, 8, 7], [83, 84, 5, 13], [89, 61, 8, 13], [23, 80, 5, 10], [74, 80, 6, 10]], [[49, 28, 12, 10], [40, 8, 6, 6], [80, 10, 4, 5], [22, 27, 4, 6], [7, 42, 9, 5], [93, 42, 9, 5], [35, 70, 4, 6], [51, 68, 6, 6], [67, 75, 4, 5], [53, 91, 7, 12]], [[14, 10, 7, 5], [36, 20, 13, 9], [83, 27, 6, 6], [73, 14, 4, 4], [10, 32, 6, 14], [95, 29, 5, 11], [25, 83, 6, 11], [49, 85, 5, 7], [81, 73, 7, 12], [63, 86, 5, 8]], [[8, 65, 5, 8], [80, 69, 6, 5], [87, 93, 12, 6], [19, 5, 9, 5], [94, 75, 7, 12], [67, 35, 3, 7], [29, 74, 6, 12], [64, 73, 8, 12], [33, 65, 3, 4], [84, 15, 9, 6]], [[25, 20, 6, 7], [50, 7, 4, 7], [66, 20, 5, 10], [94, 4, 10, 5], [17, 36, 3, 7], [58, 40, 5, 7], [26, 83, 6, 10], [53, 81, 6, 6], [76, 83, 8, 10], [83, 36, 5, 6]], [[59, 10, 6, 7], [18, 34, 6, 8], [91, 28, 6, 10], [91, 66, 7, 12], [25, 81, 7, 11], [43, 79, 7, 10], [66, 83, 8, 11], [49, 94, 11, 6], [88, 89, 9, 5], [5, 46, 4, 5]], [[92, 31, 14, 11], [35, 9, 8, 5], [94, 88, 8, 11], [96, 64, 6, 14], [12, 54, 3, 5], [28, 67, 7, 8], [52, 74, 6, 6], [76, 70, 7, 10], [23, 93, 9, 7], [85, 83, 4, 4]], [[9, 82, 10, 5], [92, 85, 9, 5], [32, 76, 4, 5], [67, 76, 4, 5], [97, 16, 3, 8], [42, 10, 7, 9], [26, 78, 6, 12], [50, 70, 5, 6], [72, 78, 7, 12], [49, 90, 4, 10]], [[49, 19, 21, 18], [18, 9, 7, 12], [85, 10, 7, 12], [7, 90, 5, 9], [86, 90, 3, 7], [49, 63, 3, 6], [26, 62, 7, 10], [51, 70, 5, 6], [69, 76, 4, 5], [73, 90, 5, 6]]];
const $=id=>document.getElementById(id);
let saved={};try{saved=JSON.parse(localStorage.getItem('huntrix-detectives-v2')||'{}')||{};}catch{}
let current=Number.isInteger(saved.current)&&saved.current>=0&&saved.current<10?saved.current:0;
let progress=Array.from({length:10},(_,i)=>new Set(Array.isArray(saved.found?.[i])?saved.found[i].filter(v=>Number.isInteger(v)&&v>=0&&v<10):[]));
let sound=saved.sound!==false,audioCtx,toastTimer,hintTimer,winTimer,missTimer,hinted=null;
const praises=['好眼力！找到一個小不同！','哇，你的眼睛會發光耶！','女孩們為你拍拍手！','又收集到一顆小星星！','小小觀察家，就是你！'];
function save(){try{localStorage.setItem('huntrix-detectives-v2',JSON.stringify({current,sound,found:progress.map(s=>[...s])}));}catch{}}
function puzzle(level){return regions[level].map((p,i)=>({x:p[0],y:p[1],rx:p[2],ry:p[3],diff:i}));}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2400);}
const cues={right:{notes:[784,1047,1319],type:'sine',step:.085,dur:.3,gain:.06},wrong:{notes:[311,233],type:'triangle',step:.14,dur:.26,gain:.05},win:{notes:[523,659,784,1046,1319],type:'sine',step:.12,dur:.34,gain:.06}};
function chime(name='right'){const cue=cues[name];if(!sound||!cue)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();cue.notes.forEach((freq,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*cue.step;o.type=cue.type;o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(cue.gain,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+cue.dur);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+cue.dur+.02);});}catch{}}
function syncSound(){$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'關閉音效':'開啟音效');}
function clearHint(){clearTimeout(hintTimer);hinted=null;document.querySelectorAll('.hint-mark').forEach(el=>el.remove());}
function render(){clearHint();clearTimeout(winTimer);const level=levels[current],found=progress[current];$('level-title').textContent=level[0];$('level-kicker').textContent=`LEVEL ${String(current+1).padStart(2,'0')} · ${level[1]}`;$('level-icon').textContent=level[2];$('levels').innerHTML=levels.map((l,i)=>`<button class="level-btn ${i===current?'active':''} ${progress[i].size===10?'complete':''}" aria-label="第${i+1}關：${l[0]}${progress[i].size===10?'，已完成':''}" ${i===current?'aria-current="step"':''} data-level="${i}">${i+1}</button>`).join('');
for(const side of ['a','b']){const scene=$('scene-'+side);scene.style.setProperty('--bg-x',current%2?'100%':'0%');scene.style.setProperty('--bg-y',`${Math.floor(current/2)*25}%`);scene.querySelector('.objects').innerHTML=puzzle(current).map((item,i)=>`<button class="object" style="--x:${item.x};--y:${item.y};--rx:${item.rx};--ry:${item.ry}" data-index="${i}" aria-label="圖片${side.toUpperCase()}，觀察區域${i+1}${found.has(item.diff)?'，已找到':''}" ${found.has(item.diff)?'disabled':''}></button>`).join('');scene.querySelector('.changes').innerHTML=side==='b'?puzzle(current).map(item=>`<div class="scene-change" style="--x:${item.x}%;--y:${item.y}%;--rx:${item.rx}%;--ry:${item.ry}%"></div>`).join(''):'';scene.querySelector('.marks').innerHTML='';}
updateProgress();for(const item of puzzle(current))if(found.has(item.diff))mark(item);save();}
function updateProgress(){const n=progress[current].size;$('found-count').textContent=n;$('stars').innerHTML=Array.from({length:10},(_,i)=>`<span class="progress-star ${i<n?'filled':''}" aria-hidden="true">★</span>`).join('');$('stars').setAttribute('aria-label',`已找到${n}個，共10個`);$('journey-count').textContent=`已完成 ${progress.filter(s=>s.size===10).length} / 10 關`;$('hint').disabled=n===10;$('encouragement').textContent=n===10?'全部找到了！你是閃亮觀察家！':n===0?'看看衣服、髮飾和背景，小不同藏在畫裡喔！':n>=7?`再找到 ${10-n} 個，就集滿星星囉！`:praises[n%praises.length];}
function miss(x,y){chime('wrong');toast('這裡一樣喔，再仔細看看衣服和背景 ♡');clearTimeout(missTimer);document.querySelectorAll('.miss-mark').forEach(el=>el.remove());for(const side of ['a','b']){const m=document.createElement('span');m.className='miss-mark';m.style.cssText=`--x:${x};--y:${y}`;$('scene-'+side).querySelector('.marks').appendChild(m);}missTimer=setTimeout(()=>document.querySelectorAll('.miss-mark').forEach(el=>el.remove()),700);}
function mark(item,hint=false){for(const side of ['a','b']){const mark=document.createElement('span');mark.className=`found-mark${hint?' hint-mark':''}`;mark.style.cssText=`--x:${item.x};--y:${item.y};--rx:${item.rx};--ry:${item.ry}`;$('scene-'+side).querySelector('.marks').appendChild(mark);}}
function select(index){const item=puzzle(current)[index];if(!item)return false;if(progress[current].has(item.diff))return false;clearHint();progress[current].add(item.diff);mark(item);for(const side of ['a','b']){const b=$('scene-'+side).querySelector(`[data-index="${index}"]`);b.disabled=true;b.setAttribute('aria-label',`圖片${side.toUpperCase()}，觀察區域${index+1}，已找到`);}updateProgress();save();chime('right');if(progress[current].size===10){$('levels').querySelector(`[data-level="${current}"]`).classList.add('complete');winTimer=setTimeout(showWin,550);}return true;}
function chooseLevel(index){if(!Number.isInteger(index)||index<0||index>=10)throw new Error('請選擇第1至10關');if($('win-dialog').open)$('win-dialog').close();current=index;render();}
function showHint(){if(progress[current].size===10)return null;clearHint();const item=puzzle(current).find(p=>p.diff!==null&&!progress[current].has(p.diff));hinted=item.diff;mark(item,true);toast('看看黃色圈圈裡，顏色或小細節有沒有改變？');hintTimer=setTimeout(clearHint,4500);return {level:current+1,x:item.x,y:item.y};}
function showWin(){chime('win');const all=progress.every(s=>s.size===10);$('win-title').textContent=all?'100 個不同，全都找到了！':'太棒了！全都找到了！';$('win-copy').textContent=all?'十顆過關星星，送給最閃亮的小小觀察家！':'10 個小不同，都逃不過你的眼睛。';$('next').textContent=all?'再玩一次這一關 ↻':current===9?'繼續收集星星 →':'下一關，出發！ →';$('win-dialog').showModal();}
$('levels').addEventListener('click',e=>{const b=e.target.closest('[data-level]');if(b)chooseLevel(Number(b.dataset.level));});
for(const side of ['a','b'])$('scene-'+side).addEventListener('click',e=>{const b=e.target.closest('[data-index]');if(b&&e.detail===0){select(Number(b.dataset.index));return;}const r=e.currentTarget.getBoundingClientRect();const x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;const index=puzzle(current).map((p,i)=>({index:i,d:((p.x-x)/(p.rx+1.2))**2+((p.y-y)/(p.ry+1.8))**2})).filter(p=>p.d<=1).sort((a,b)=>a.d-b.d)[0]?.index??-1;if(index>=0)select(index);else miss(x,y);});
$('hint').addEventListener('click',showHint);$('restart').addEventListener('click',()=>{progress[current]=new Set();render();toast('星星準備好了，一起重新找！');});$('sound').addEventListener('click',()=>{sound=!sound;syncSound();save();chime('right');toast(sound?'音效開啟 ♫':'音效已關閉');});$('help').addEventListener('click',()=>$('help-dialog').showModal());document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$('stay').addEventListener('click',()=>$('win-dialog').close());$('next').addEventListener('click',()=>{if(progress.every(s=>s.size===10)){progress[current]=new Set();chooseLevel(current);}else chooseLevel(current<9?current+1:progress.findIndex(s=>s.size<10));});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
syncSound();render();
const context=document.modelContext;if(context?.registerTool){for(const tool of [{name:'get_game_progress',description:'Read current level, found differences, and completed levels.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({level:current+1,found:progress[current].size,totalDifferences:10,totalLevels:10,completed:progress.map((s,i)=>s.size===10?i+1:null).filter(Boolean)})},{name:'choose_game_level',description:'Choose a level from 1 to 10, keeping progress.',inputSchema:{type:'object',properties:{level:{type:'integer',minimum:1,maximum:10}},required:['level'],additionalProperties:false},execute:input=>{chooseLevel(input.level-1);return {level:current+1,found:progress[current].size};}},{name:'show_game_hint',description:'Temporarily highlight an unfound difference in both pictures without marking it found.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>showHint()}]){try{Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}}}
